<?php
namespace Modules\BankingMicrofinanceTreasury\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryInterBranchTransfer;use Modules\BankingMicrofinanceTreasury\Entities\TreasuryVault;use Modules\BankingMicrofinanceTreasury\Services\TreasuryNumberService;use Modules\BankingMicrofinanceTreasury\Services\TreasuryPostingService;
class InterBranchTransferController extends Controller{public function index(){return view('bankingmicrofinancetreasury::transfers.index',['transfers'=>TreasuryInterBranchTransfer::latest()->paginate(25)]);}public function create(TreasuryNumberService $numbers){return view('bankingmicrofinancetreasury::transfers.form',['transfer'=>new TreasuryInterBranchTransfer(['transfer_no'=>$numbers->next('IBT'),'transfer_date'=>date('Y-m-d')]),'vaults'=>TreasuryVault::where('status','active')->get()]);}public function store(Request $r){TreasuryInterBranchTransfer::create($r->all()+['business_id'=>auth()->user()->business_id ?? null,'requested_by'=>auth()->id()]);return redirect()->route('bkg.mfi.treasury.inter-branch-transfers.index')->with('status','Transfer saved');}public function edit(TreasuryInterBranchTransfer $transfer){return view('bankingmicrofinancetreasury::transfers.form',['transfer'=>$transfer,'vaults'=>TreasuryVault::where('status','active')->get()]);}public function update(Request $r,TreasuryInterBranchTransfer $transfer){abort_if(in_array($transfer->status,['posted','cancelled']),403);$transfer->update($r->all());return redirect()->route('bkg.mfi.treasury.inter-branch-transfers.index')->with('status','Transfer updated');}public function submit(TreasuryInterBranchTransfer $transfer){$transfer->update(['status'=>'submitted']);return back();}public function approve(TreasuryInterBranchTransfer $transfer){$transfer->update(['status'=>'approved','approved_by'=>auth()->id(),'approved_at'=>now()]);return back();}public function post(TreasuryInterBranchTransfer $transfer,TreasuryPostingService $posting){$posting->postTransfer($transfer,auth()->id());return back()->with('status','Transfer posted');}public function destroy(TreasuryInterBranchTransfer $transfer){$transfer->delete();return back();}}
